import { chromium } from 'playwright';

const BASE = 'http://localhost:3100';
const routes = ['/', '/about', '/pro', '/terms', '/extension', '/learn', '/wiki', '/dictionary', '/tools', '/tools/calculator', '/tools/pricing', '/agents', '/instructions'];

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
const findings = [];

for (const route of routes) {
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  const resp = await page.goto(BASE + route, { waitUntil: 'networkidle', timeout: 30000 }).catch(e => ({ _err: e.message }));
  const status = resp && resp.status ? resp.status() : ('NAV_FAIL: ' + (resp?._err || '?'));
  // broken images
  const brokenImgs = await page.$$eval('img', imgs => imgs.filter(i => i.complete && i.naturalWidth === 0).map(i => i.currentSrc || i.src));
  findings.push({ route, status, errors, brokenImgs });
  if (route === '/') {
    await page.screenshot({ path: 'scripts/qa-hero.png', clip: { x: 0, y: 0, width: 1280, height: 760 } });
  }
  await page.close();
}

await browser.close();
for (const f of findings) {
  const flag = (f.status !== 200 || f.errors.length || f.brokenImgs.length) ? 'X' : 'ok';
  console.log(`[${flag}] ${f.route}  status=${f.status}  errors=${f.errors.length}  brokenImgs=${f.brokenImgs.length}`);
  f.errors.forEach(e => console.log('    ERR: ' + e.slice(0, 200)));
  f.brokenImgs.forEach(b => console.log('    IMG: ' + b));
}

