639	  /**
640	   * /terminology-gen -- Scan for terminology sources and show compression potential
641	   */
642	  private async handleTerminologyGen(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
643	    stream.progress('Scanning project for terminology sources...');
644	
645	    const folders = vscode.workspace.workspaceFolders;
646	    if (!folders) {
647	      stream.markdown('No workspace open.\n');
648	      return {};
649	    }
650	
651	    const root = folders[0].uri;
652	
653	    const dictPattern = new vscode.RelativePattern(root, '**/dictionary.json');
654	    const dictFiles = await vscode.workspace.findFiles(dictPattern, '**/node_modules/**', 5);
655	
656	    const termPattern = new vscode.RelativePattern(root, '**/terminologies.md');
657	    const termFiles = await vscode.workspace.findFiles(termPattern, '**/node_modules/**', 5);
658	
659	    stream.markdown(`## Terminology Generator\n\n`);
660	    stream.markdown(`### Sources Found\n\n`);
661	    stream.markdown(`| Source | Status |\n|---|---|\n`);
662	    stream.markdown(`| \`dictionary.json\` | ${dictFiles.length > 0 ? dictFiles.length + ' file(s)' : 'Not found'} |\n`);
663	    stream.markdown(`| \`terminologies.md\` | ${termFiles.length > 0 ? termFiles.length + ' file(s)' : 'Not found'} |\n\n`);
664	
665	    if (dictFiles.length === 0 && termFiles.length === 0) {
666	      stream.markdown(`No terminology sources found. Create a \`content/dictionary.json\` with:\n\n`);
667	      stream.markdown('```json\n{\n  "terms": [\n    { "term": "Context Rot", "definition": "...", "category": "context-management", "tags": [] }\n  ]\n}\n```\n\n');
668	      stream.markdown(`Then run \`@tokalator /terminology-gen\` again.\n`);
669	      return {};
670	    }
671	
672	    let totalSourceTokens = 0;
673	    for (const uri of [...dictFiles, ...termFiles]) {
674	      try {
675	        const doc = await vscode.workspace.openTextDocument(uri);
676	        const model = this.monitor.getActiveModel();
677	        const tokenizer = this.monitor.getTokenizer();
678	        const tokens = tokenizer.countTokens(doc.getText(), model.provider);
679	        totalSourceTokens += tokens;
680	        stream.markdown(`- \`${vscode.workspace.asRelativePath(uri)}\`: ~${this.fmtTokens(tokens)} tokens\n`);
681	      } catch { /* skip */ }
682	    }
683	
684	    const instrPattern = new vscode.RelativePattern(root, '**/.github/instructions/terminology.instructions.md');
685	    const instrFiles = await vscode.workspace.findFiles(instrPattern, undefined, 1);
