6	
7	export class ContextDashboardProvider implements vscode.WebviewViewProvider, vscode.Disposable {
8	
9	  public static readonly viewType = 'tokalator.dashboard';
10	
11	  private view?: vscode.WebviewView;
12	  private readonly _snapshotListener: vscode.Disposable;
13	  private readonly _catalogListener: vscode.Disposable;
14	
15	  constructor(
16	    private readonly extensionUri: vscode.Uri,
17	    private readonly monitor: ContextMonitor,
18	  ) {
19	    this._snapshotListener = this.monitor.onDidUpdateSnapshot(snapshot => {
20	      this.postSnapshot(snapshot);
21	    });
22	    this._catalogListener = onDidChangeCatalog(() => {
23	      const snapshot = this.monitor.getLatestSnapshot();
24	      if (snapshot) { this.postSnapshot(snapshot); }
25	    });
26	  }
27	
28	  dispose(): void {
29	    this._snapshotListener.dispose();
30	    this._catalogListener.dispose();
31	  }
32	
33	  resolveWebviewView(
34	    webviewView: vscode.WebviewView,
35	    _context: vscode.WebviewViewResolveContext,
36	    _token: vscode.CancellationToken,
37	  ): void {
38	    this.view = webviewView;
39	
40	    webviewView.webview.options = {
41	      enableScripts: true,
42	      localResourceRoots: [this.extensionUri],
43	    };
44	
45	    webviewView.onDidChangeVisibility(() => {
46	      if (webviewView.visible) {
47	        const snapshot = this.monitor.getLatestSnapshot();
48	        if (snapshot) {
49	          this.postSnapshot(snapshot);
50	        }
51	      }
52	    });
53	
54	    webviewView.onDidDispose(() => {
55	      this.view = undefined;
56	    });
57	
58	    webviewView.webview.html = this.getHtml(webviewView.webview);
59	
60	    webviewView.webview.onDidReceiveMessage(async (message) => {
61	      switch (message.command) {
62	        case 'optimize': {
63	          const closed = await this.monitor.optimizeTabs();
64	          vscode.window.showInformationMessage(
65	            closed.length > 0
66	              ? `Closed ${closed.length} tabs: ${closed.join(', ')}`
67	              : 'All tabs are relevant'
68	          );
69	          this.monitor.refresh();
70	          break;
71	        }
72	
73	        case 'pin': {
74	          this.monitor.pinFile(message.uri);
75	          break;
76	        }
77	
78	        case 'unpin': {
79	          this.monitor.unpinFile(message.uri);
80	          break;
81	        }
82	
83	        case 'closeTab': {
84	          const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
85	          const targetTab = allTabs.find(t => {
86	            if (t.input instanceof vscode.TabInputText) {
87	              return t.input.uri.toString() === message.uri;
88	            }
89	            return false;
90	          });
91	          if (targetTab) {
92	            await vscode.window.tabGroups.close(targetTab);
93	          }
94	          this.monitor.refresh();
95	          break;
96	        }
97	
98	        case 'openFile': {
99	          const doc = await vscode.workspace.openTextDocument(vscode.Uri.parse(message.uri));
100	          await vscode.window.showTextDocument(doc);
101	          break;
102	        }
103	
104	        case 'refresh': {
105	          this.monitor.refresh();
106	          break;
107	        }
108	
109	        case 'resetTurns': {
110	          this.monitor.resetChatTurns();
111	          break;
112	        }
113	
114	        case 'setModel': {
115	          await this.monitor.setModel(message.modelId);
116	          break;
117	        }
118	
119	        case 'refreshPricing': {
120	          await vscode.commands.executeCommand('tokalator.refreshPricing');
121	          break;
122	        }
123	
124	        case 'terminologyGen': {
125	          await vscode.commands.executeCommand('workbench.action.chat.open', { query: '@tokalator /terminology-gen' });
126	          break;
127	        }
128	
129	        case 'proFeature': {
130	          const action = await vscode.window.showInformationMessage(
131	            `${message.feature} is a Tokalator Pro feature. Upgrade for secure workspaces, SKILL.md generation, AI settings, and more.`,
132	            'Learn More'
133	          );
134	          if (action === 'Learn More') {
135	            vscode.env.openExternal(vscode.Uri.parse('https://tokalator.ai'));
136	          }
137	          break;
138	        }
139	      }
140	    });
